GPU_MEM_SIZE = 80 # GB

# EVOLVE-BLOCK-START

def compute_model_placement(gpu_num, models):
    """
    Greedy placement followed by local-search refinement (moves and swaps)
    that repeatedly reduces the maximum KVPR across GPUs.
    """
    if not models:
        return {gpu_id: [] for gpu_id in range(gpu_num)}

    def kvprs(load, free):
        return [load[i] / free[i] if free[i] > 0 else float('inf') for i in range(len(load))]

    def greedy(order):
        placement = {g: [] for g in range(gpu_num)}
        free = [GPU_MEM_SIZE] * gpu_num
        load = [0.0] * gpu_num
        for model in order:
            best, best_r = None, float('inf')
            for g in range(gpu_num):
                if model.model_size <= free[g]:
                    r = load[g] / free[g]
                    if r < best_r:
                        best_r, best = r, g
            if best is None:
                return None, None, None
            placement[best].append(model)
            load[best] += model.req_rate / model.slo
            free[best] -= model.model_size
        return placement, load, free

    # Lower-bound-guided construction: target the analytic LP bound
    # L = (sum req_rate/slo) / (gpus * MEM - sum sizes), assigning each model
    # to the GPU whose post-placement KVPR lands closest to L (equalizing
    # per-GPU pressure toward the analytic optimum) instead of greedily
    # minimizing each step. Falls back to incumbent greedy when infeasible.
    total_load = sum(m.req_rate / m.slo for m in models)
    total_free = gpu_num * GPU_MEM_SIZE - sum(m.model_size for m in models)
    L = total_load / total_free if total_free > 0 else float('inf')

    def target_greedy(order):
        placement = {g: [] for g in range(gpu_num)}
        free = [float(GPU_MEM_SIZE)] * gpu_num
        load = [0.0] * gpu_num
        for model in order:
            w = model.req_rate / model.slo
            best, best_key = None, None
            for g in range(gpu_num):
                denom = free[g] - model.model_size
                if denom <= 1e-12:
                    continue
                post = (load[g] + w) / denom
                # Prefer landing at or below the LP bound L; penalize overshoot.
                key = (post > L, abs(post - L), -free[g])
                if best_key is None or key < best_key:
                    best_key, best = key, g
            if best is None:
                return None, None, None
            placement[best].append(model)
            load[best] += w
            free[best] -= model.model_size
        return placement, load, free

    # Try target-greedy for a few orderings, keeping the best of
    # target-greedy AND plain greedy per ordering (target-greedy equalizes
    # toward the LP bound, but plain greedy can win on tight instances).
    best = None
    for order in (
        sorted(models, key=lambda m: m.req_rate / m.slo, reverse=True),
        sorted(models, key=lambda m: m.model_size, reverse=True),
        sorted(models, key=lambda m: m.req_rate / m.slo / m.model_size, reverse=True),
    ):
        for p, l, f in (target_greedy(order), greedy(order)):
            if p is not None and (best is None or max(kvprs(l, f)) < best[1]):
                best = (p, max(kvprs(l, f)), l, f)
    if best is None:
        raise ValueError("Unable to place models on any GPU within memory limits.")
    placement, cur_max, load, free = best

    # Simulated annealing over assignment vector to escape greedy local minima
    import numpy as np
    rng = np.random.default_rng(0)
    sizes = [m.model_size for m in models]
    weights = [m.req_rate / m.slo for m in models]
    n = len(models)

    x = [0] * n
    for g in range(gpu_num):
        for m in placement[g]:
            x[models.index(m)] = g

    # Seed list will hold the target-greedy assignment; plain-greedy seed added below.
    seeds = []
    def objective(assign):
        lo = [0.0] * gpu_num
        used = [0.0] * gpu_num
        for i, g in enumerate(assign):
            lo[g] += weights[i]
            used[g] += sizes[i]
        return max(lo[g] / (GPU_MEM_SIZE - used[g]) if used[g] < GPU_MEM_SIZE else float('inf')
                   for g in range(gpu_num))

    cur = objective(x)
    best_x, best = x[:], cur
    # Secondary seed: also track the plain-greedy solution as an SA start.
    seeds = [x[:]]

    # Pareto-knapsack-frontier decomposition seed: for each GPU in turn, run a
    # subset-sum DP over the remaining models (memory scaled to 0.1 GB units,
    # capped at GPU_MEM_SIZE) tracking the minimum load per memory level with
    # backpointers, prune dominated (mem, load) states, then pick the frontier
    # point whose KVPR lands closest to a target ratio and realize it via
    # backtracking. Iterate over a SNAPSHOT of states each pass so a model is
    # never added twice within one DP pass. Remainder overflow is redistributed
    # to other GPUs' slack. Several targets around the LP bound L are tried;
    # each realized assignment is accepted directly if it beats the incumbent
    # and is appended as an SA seed.
    SCALE = 10  # 0.1 GB units; 800 units == 80 GB

    def dp_frontier(idx_list):
        states = {0: (0.0, -1, 0)}  # mem_units -> (load, model_idx, prev_mem)
        for i in idx_list:
            s = int(round(models[i].model_size * SCALE))
            w = weights[i]
            snapshot = list(states.items())
            for m, (l0, _, _) in snapshot:
                nm = m + s
                if nm > GPU_MEM_SIZE * SCALE:
                    continue
                nl = l0 + w
                cur = states.get(nm)
                if cur is None or nl < cur[0]:
                    states[nm] = (nl, i, m)
        # Dominance pruning: keep only states with strictly decreasing min load.
        pruned = {}
        min_load = float('inf')
        for m in sorted(states):
            if states[m][0] < min_load:
                min_load = states[m][0]
                pruned[m] = states[m]
        return pruned

    def realize(target):
        remaining = list(range(n))
        x_dp = [-1] * n
        for g in range(gpu_num - 1):
            if not remaining:
                break
            states = dp_frontier(remaining)
            best_key, best_m = None, None
            for m, (l0, _, _) in states.items():
                free_mem = GPU_MEM_SIZE - m / SCALE
                if free_mem <= 1e-9:
                    continue
                r = l0 / free_mem
                key = (r > target, abs(r - target))
                if best_key is None or key < best_key:
                    best_key, best_m = key, m
            if best_m is None or best_m == 0:
                continue
            m = best_m
            while m != 0:
                x_dp[states[m][1]] = g
                m = states[m][2]
            remaining = [i for i in remaining if x_dp[i] == -1]
        for i in remaining:
            x_dp[i] = gpu_num - 1
        used = [0.0] * gpu_num
        for i, g in enumerate(x_dp):
            used[g] += sizes[i]
        # Redistribute overflow from the remainder GPU into other GPUs' slack.
        rem = gpu_num - 1
        for i in sorted([i for i in range(n) if x_dp[i] == rem],
                        key=lambda i: -sizes[i]):
            if used[rem] <= GPU_MEM_SIZE:
                break
            cands = [g for g in range(rem) if used[g] + sizes[i] <= GPU_MEM_SIZE]
            if cands:
                g = min(cands, key=lambda gg: used[gg])
                used[g] += sizes[i]
                used[rem] -= sizes[i]
                x_dp[i] = g
        if used[rem] > GPU_MEM_SIZE:
            return None
        return x_dp

    for target in (L, L * 0.95, L * 1.05, L * 0.8):
        dx = realize(target)
        if dx is not None:
            seeds.append(dx)
            dv = objective(dx)
            if dv < best:
                best_x, best = dx[:], dv
    T0 = max(cur / 10.0, 1e-3)
    iters = 20000
    for it in range(iters):
        T = T0 * (1e-4 / T0) ** (it / iters)
        cand = x[:]
        i = rng.integers(n)
        if rng.random() < 0.5:
            cand[i] = int(rng.integers(gpu_num))
        else:
            j = int(rng.integers(n))
            cand[i], cand[j] = cand[j], cand[i]
        used = [0.0] * gpu_num
        for k, g in enumerate(cand):
            used[g] += sizes[k]
        if any(u > GPU_MEM_SIZE for u in used):
            continue
        cv = objective(cand)
        if cv < cur or rng.random() < np.exp((cur - cv) / max(T, 1e-12)):
            x, cur = cand, cv
            if cur < best:
                best_x, best = x[:], cur

    # Re-run SA from the alternate seed (greedy ordering) with a fresh schedule.
    for seed in seeds[1:]:
        x, cur = seed[:], objective(seed)
        if cur < best:
            best_x, best = x[:], cur
        for it in range(iters):
            T = T0 * (1e-4 / T0) ** (it / iters)
            cand = x[:]
            i = rng.integers(n)
            if rng.random() < 0.5:
                cand[i] = int(rng.integers(gpu_num))
            else:
                j = int(rng.integers(n))
                cand[i], cand[j] = cand[j], cand[i]
            used = [0.0] * gpu_num
            for k, g in enumerate(cand):
                used[g] += sizes[k]
            if any(u > GPU_MEM_SIZE for u in used):
                continue
            cv = objective(cand)
            if cv < cur or rng.random() < np.exp((cur - cv) / max(T, 1e-12)):
                x, cur = cand, cv
                if cur < best:
                    best_x, best = x[:], cur

    placement = {g: [] for g in range(gpu_num)}
    for i, g in enumerate(best_x):
        placement[g].append(models[i])
    return placement

